-- Generated from database/source/CookBuddy_Mapping_Review.xlsx.
-- Rebuild with: python3 scripts/generate_seed_from_mapping.py
BEGIN;

TRUNCATE recipe_ingredients, recipe_pairings, recipe_tags, ingredient_aliases, recipes, ingredients RESTART IDENTITY CASCADE;

ON CONFLICT (name) DO UPDATE SET category = EXCLUDED.category, default_unit = EXCLUDED.default_unit;

ON CONFLICT (source_id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, instructions = EXCLUDED.instructions, prep_time_minutes = EXCLUDED.prep_time_minutes, cook_time_minutes = EXCLUDED.cook_time_minutes, servings = EXCLUDED.servings, cuisine = EXCLUDED.cuisine, diet_type = EXCLUDED.diet_type, difficulty = EXCLUDED.difficulty, image_url = EXCLUDED.image_url, emotional_state = EXCLUDED.emotional_state, late_night = EXCLUDED.late_night, low_effort = EXCLUDED.low_effort, sick_day = EXCLUDED.sick_day, budget_friendly = EXCLUDED.budget_friendly, summer_cooling = EXCLUDED.summer_cooling, light_meal = EXCLUDED.light_meal, one_pot = EXCLUDED.one_pot, minimal_cleanup = EXCLUDED.minimal_cleanup, study_snack = EXCLUDED.study_snack, weekend_special = EXCLUDED.weekend_special, effort_score = EXCLUDED.effort_score, comfort_score = EXCLUDED.comfort_score, energy_score = EXCLUDED.energy_score, soul_food_score = EXCLUDED.soul_food_score, rainy_day_score = EXCLUDED.rainy_day_score, protein_score = EXCLUDED.protein_score, nostalgia_score = EXCLUDED.nostalgia_score, stomach_feel = EXCLUDED.stomach_feel, best_time = EXCLUDED.best_time, best_day = EXCLUDED.best_day, tomo_line = EXCLUDED.tomo_line, home_style_score = EXCLUDED.home_style_score;

ON CONFLICT (recipe_id, ingredient_id) DO UPDATE SET quantity = EXCLUDED.quantity, unit = EXCLUDED.unit, role = EXCLUDED.role, is_main = EXCLUDED.is_main, match_weight = EXCLUDED.match_weight;

ON CONFLICT (recipe_id, tag) DO UPDATE SET tag_type = EXCLUDED.tag_type;

ON CONFLICT (id) DO UPDATE SET paired_recipe_id = EXCLUDED.paired_recipe_id, pairing_message = EXCLUDED.pairing_message, pairing_strength = EXCLUDED.pairing_strength;

ON CONFLICT (ingredient_id, alias_name) DO NOTHING;

COMMIT;
