INSERT INTO recipes (id, title, description, instructions, prep_time_minutes, cook_time_minutes, servings, cuisine, diet_type, difficulty, image_url, source_id, emotional_state, late_night, low_effort, sick_day, budget_friendly, summer_cooling, light_meal, one_pot, minimal_cleanup, study_snack, weekend_special, effort_score, comfort_score, energy_score, soul_food_score, rainy_day_score, protein_score, nostalgia_score, stomach_feel, best_time, best_day, tomo_line, home_style_score) VALUES
  ('7f5cea1c-ca9d-5adb-a77b-ddab3402bdee', 'Aloo Paratha', 'Aloo Paratha is a home-style morning idea made with wheat and potato. It has the soft, familiar comfort of food you would happily eat at home on a slower day. Serve it warm, adjust the spice to your mood, and pair it with a simple side if you want the plate to feel complete.', ARRAY['Prep wheat and potato so everything is ready before the pan gets hot.', 'Start with the usual home base of oil or ghee, onion, tomato, herbs, or spices as the dish needs.', 'Cook gently until the flavours come together, then finish the Aloo Paratha with salt, heat, and texture adjusted to taste.', 'Serve warm while it still feels fresh and comforting.'], 10, 20, 2, 'Indian', 'vegetarian', 'easy', '/assets/images/dishes/aloo-paratha.png', 'aloo-paratha-breakfast', NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 5, 8, 5, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('eac23e09-f8ae-56e9-b0cf-6451426f8a62', 'Andhra Chicken Curry', 'Andhra Chicken Curry is a home-style midday idea made with chicken, onion, red chilli, and curry leaves. It brings a lively chilli warmth without losing that familiar home-cooked comfort. Serve it warm, adjust the spice to your mood, and pair it with a simple side if you want the plate to feel complete.', ARRAY['Prep chicken, onion, red chilli, and curry leaves so everything is ready before the pan gets hot.', 'Start with the usual home base of oil or ghee, onion, tomato, herbs, or spices as the dish needs.', 'Cook gently until the flavours come together, then finish the Andhra Chicken Curry with salt, heat, and texture adjusted to taste.', 'Serve warm while it still feels fresh and comforting.'], 10, 45, 2, 'Indian', 'non-vegetarian', 'easy', '/assets/images/dishes/chicken-curry-rice.png', 'andhra-chicken-curry', 'hungry, tired_after_work', FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 8, 8, 6, 6, 8, 9, 6, 'heavy', 'dinner', 'weekday', '🍅 Something filling and comforting tonight?', 9),
  ('48e908cd-ad9d-5c8c-8496-83f522dca7d6', 'Andhra Podi Idli', 'Andhra Podi Idli is a home-style morning idea made with idli, podi, and ghee. It brings a lively chilli warmth without losing that familiar home-cooked comfort. Serve it warm, adjust the spice to your mood, and pair it with a simple side if you want the plate to feel complete.', ARRAY['Prep idli, podi, and ghee so everything is ready before the pan gets hot.', 'Start with the usual home base of oil or ghee, onion, tomato, herbs, or spices as the dish needs.', 'Cook gently until the flavours come together, then finish the Andhra Podi Idli with salt, heat, and texture adjusted to taste.', 'Serve warm while it still feels fresh and comforting.'], 6, 14, 2, 'Indian', 'vegetarian', 'easy', '/assets/images/dishes/idli.png', 'andhra-podi-idli', 'morning_energy', TRUE, TRUE, FALSE, TRUE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 3, 8, 3, 8, 7, 4, 7, 'light', 'breakfast', 'weekday', '🍅 Spicy podi idli to wake up the day!', 9),
  ('9c8a6733-ecd6-5340-8030-896f40b4f119', 'Apple Puree', 'Apple Puree is a home-style dinner idea made with apple and milk. It has the soft, familiar comfort of food you would happily eat at home on a slower day. Serve it warm, adjust the spice to your mood, and pair it with a simple side if you want the plate to feel complete.', ARRAY['Prep apple and milk so everything is ready before the pan gets hot.', 'Start with the usual home base of oil or ghee, onion, tomato, herbs, or spices as the dish needs.', 'Cook gently until the flavours come together, then finish the Apple Puree with salt, heat, and texture adjusted to taste.', 'Serve warm while it still feels fresh and comforting.'], 10, 20, 2, 'Indian', 'vegetarian', 'easy', '/assets/images/dishes/dinner-default.png', 'apple-puree-snack', NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, 5, 8, 3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('cb7e1bda-4c58-563b-bcd3-3dde4ce33b3f', 'Avalakki', 'Avalakki is a home-style morning idea made with poha and onion. It comes together quickly, so it works well when you want real food without a long cooking session. Serve it warm, adjust the spice to your mood, and pair it with a simple side if you want the plate to feel complete.', ARRAY['Prep poha and onion so everything is ready before the pan gets hot.', 'Start with the usual home base of oil or ghee, onion, tomato, herbs, or spices as the dish needs.', 'Cook gently until the flavours come together, then finish the Avalakki with salt, heat, and texture adjusted to taste.', 'Serve warm while it still feels fresh and comforting.'], 10, 20, 2, 'Indian', 'vegetarian', 'easy', '/assets/images/dishes/breakfast-default.png', 'avalakki-breakfast', NULL, TRUE, TRUE, FALSE, TRUE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 5, 5, 3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
