  ('9927a138-c633-543e-94b4-927f1c75e5f7', 'Spicy Aloo Paratha', 'Spicy Aloo Paratha is a home-style morning idea made with wheat flour, potato, green chilli, and ghee. It brings a lively chilli warmth without losing that familiar home-cooked comfort. Serve it warm, adjust the spice to your mood, and pair it with a simple side if you want the plate to feel complete.', ARRAY['Prep wheat flour, potato, green chilli, and ghee so everything is ready before the pan gets hot.', 'Start with the usual home base of oil or ghee, onion, tomato, herbs, or spices as the dish needs.', 'Cook gently until the flavours come together, then finish the Spicy Aloo Paratha with salt, heat, and texture adjusted to taste.', 'Serve warm while it still feels fresh and comforting.'], 10, 25, 2, 'Indian', 'vegetarian', 'easy', '/assets/images/dishes/aloo-paratha.png', 'spicy-aloo-paratha', 'family_time, relaxed', FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 5, 10, 5, 9, 9, 4, 10, 'filling', 'breakfast', 'weekend', '🍅 Feels like an aloo paratha kind of morning 😄', 10),
  ('5d7a89df-4ba0-521f-bf52-519540ac1cc6', 'Spicy Masala Dosa', 'Spicy Masala Dosa is a home-style morning idea made with dosa batter, potato, green chilli, and onion. It brings a lively chilli warmth without losing that familiar home-cooked comfort. Serve it warm, adjust the spice to your mood, and pair it with a simple side if you want the plate to feel complete.', ARRAY['Prep dosa batter, potato, green chilli, and onion so everything is ready before the pan gets hot.', 'Start with the usual home base of oil or ghee, onion, tomato, herbs, or spices as the dish needs.', 'Cook gently until the flavours come together, then finish the Spicy Masala Dosa with salt, heat, and texture adjusted to taste.', 'Serve warm while it still feels fresh and comforting.'], 10, 20, 2, 'Indian', 'vegetarian', 'easy', '/assets/images/dishes/dosa.png', 'spicy-masala-dosa', 'comfort_craving', TRUE, TRUE, FALSE, TRUE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, 5, 8, 3, 7, 7, 6, 7, 'medium', 'dinner', 'weekend', '🍅 Something comforting sounds right today.', 9),
  ('188f3314-71f4-5eba-8b4d-51bd1083084b', 'Sticky Rice', 'Sticky Rice is a home-style morning idea made with rice and sesame oil. It feels especially right on a rainy day, when you want something warm, crisp, or soothing. Serve it warm, adjust the spice to your mood, and pair it with a simple side if you want the plate to feel complete.', ARRAY['Prep rice and sesame oil so everything is ready before the pan gets hot.', 'Start with the usual home base of oil or ghee, onion, tomato, herbs, or spices as the dish needs.', 'Cook gently until the flavours come together, then finish the Sticky Rice with salt, heat, and texture adjusted to taste.', 'Serve warm while it still feels fresh and comforting.'], 10, 20, 2, 'Indian', 'non-vegetarian', 'medium', '/assets/images/dishes/breakfast-default.png', 'sticky-rice-breakfast', NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, 5, 7, 5, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('3bc2b280-cc5c-5f34-8725-54f5f6b077d5', 'Stuffed Paratha', 'Stuffed Paratha is a home-style morning idea made with wheat and potato. It has the soft, familiar comfort of food you would happily eat at home on a slower day. Serve it warm, adjust the spice to your mood, and pair it with a simple side if you want the plate to feel complete.', ARRAY['Prep wheat and potato so everything is ready before the pan gets hot.', 'Start with the usual home base of oil or ghee, onion, tomato, herbs, or spices as the dish needs.', 'Cook gently until the flavours come together, then finish the Stuffed Paratha with salt, heat, and texture adjusted to taste.', 'Serve warm while it still feels fresh and comforting.'], 10, 20, 2, 'Indian', 'vegetarian', 'easy', '/assets/images/dishes/paratha.png', 'stuffed-paratha-breakfast', NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 5, 8, 5, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
